values ('omadacycline', $q$أومادا سايكلين$q$, $q$Omadacycline$q$, 'reserve', $q$تتراسيكلينات (أمينوميثيل سايكلين)$q$, $q$Tetracyclines (aminomethylcycline)$q$, $q$التهاب الرئة الجرثومي المكتسب من المجتمع، وعدوى الجلد الجرثومية الحادة، للبالغين.$q$, $q$Community-acquired bacterial pneumonia and acute bacterial skin infections in adults.$q$, $q$التهاب الرئة: اليوم الأول 200 ملغ وريدياً (أو 100 ملغ مرتين) أو 300 ملغ فموياً مرتين، ثم 100 ملغ وريدياً أو 300 ملغ فموياً مرة يومياً. الجلد: اليوم الأول 200 ملغ وريدياً (أو 100 ملغ مرتين)، أو 450 ملغ فموياً مرة يومياً في اليومين الأول والثاني، ثم 100 ملغ وريدياً أو 300 ملغ فموياً مرة يومياً. المدة 7 إلى 14 يوماً.$q$, $q$Pneumonia: day 1, 200 mg IV (or 100 mg twice) or 300 mg by mouth twice, then 100 mg IV or 300 mg by mouth once a day. Skin: day 1, 200 mg IV (or 100 mg twice), or 450 mg by mouth once a day on days 1 and 2, then 100 mg IV or 300 mg by mouth once a day. 7 to 14 days.$q$, $q$لا تعديل في ضعف الكلى أو الكبد، ولا مع الغسيل.$q$, $q$No change for kidney or liver impairment, or dialysis.$q$, $q$الأقراص: صيام 4 ساعات قبلها، ثم بالماء فقط، ولا طعام أو شراب ساعتين بعدها، ولا ألبان أو مضادات حموضة أو فيتامينات 4 ساعات. الوريدي لا يُعطى مع محاليل الكالسيوم أو المغنيسيوم في الخط نفسه.$q$, $q$Tablets: fast for 4 hours before, take with water only, no food or drink for 2 hours after, and no dairy, antacids or multivitamins for 4 hours. IV: not with calcium or magnesium solutions in the same line.$q$, '{91}', 910, false, false, false)
on conflict (id) do update set name_ar = excluded.name_ar, name_en = excluded.name_en, aware = excluded.aware, class_ar = excluded.class_ar, class_en = excluded.class_en, uses_ar = excluded.uses_ar, uses_en = excluded.uses_en, dose_ar = excluded.dose_ar, dose_en = excluded.dose_en, renal_ar = excluded.renal_ar, renal_en = excluded.renal_en, timing_ar = excluded.timing_ar, timing_en = excluded.timing_en, source_ids = excluded.source_ids, sort = excluded.sort, reviewed = false, deleted = false, updated_at = now();
delete from public.antibiotic_interactions where drug_id = 'omadacycline';
values ('eravacycline', $q$إيرافا سايكلين$q$, $q$Eravacycline$q$, 'reserve', $q$تتراسيكلينات (فلوروسايكلين)$q$, $q$Tetracyclines (fluorocycline)$q$, $q$عدوى البطن المعقدة للبالغين.$q$, $q$Complicated intra-abdominal infection in adults.$q$, $q$1 ملغ/كغ كل 12 ساعة وريدياً خلال 60 دقيقة تقريباً، 4 إلى 14 يوماً.$q$, $q$1 mg/kg every 12 h IV over about 60 minutes, for 4 to 14 days.$q$, $q$لا تعديل في ضعف الكلى. ضعف الكبد الشديد (Child-Pugh C): 1 ملغ/كغ كل 12 ساعة في اليوم الأول، ثم كل 24 ساعة.$q$, $q$No change for kidney impairment. Severe liver impairment (Child-Pugh C): 1 mg/kg every 12 h on day 1, then every 24 h.$q$, $q$تسريب وريدي خلال 60 دقيقة تقريباً.$q$, $q$IV infusion over about 60 minutes.$q$, '{92}', 920, false, false, false)
on conflict (id) do update set name_ar = excluded.name_ar, name_en = excluded.name_en, aware = excluded.aware, class_ar = excluded.class_ar, class_en = excluded.class_en, uses_ar = excluded.uses_ar, uses_en = excluded.uses_en, dose_ar = excluded.dose_ar, dose_en = excluded.dose_en, renal_ar = excluded.renal_ar, renal_en = excluded.renal_en, timing_ar = excluded.timing_ar, timing_en = excluded.timing_en, source_ids = excluded.source_ids, sort = excluded.sort, reviewed = false, deleted = false, updated_at = now();
delete from public.antibiotic_interactions where drug_id = 'eravacycline';
values ('moxi', $q$موكسيفلوكساسين$q$, $q$Moxifloxacin$q$, 'watch', $q$فلوروكينولونات$q$, $q$Fluoroquinolones$q$, $q$التهاب الرئة المكتسب، وعدوى الجلد البسيطة والمعقدة، وعدوى البطن المعقدة، والطاعون، والتهاب الجيوب الحاد، وتفاقم التهاب القصبات المزمن (للجيوب والقصبات عند عدم وجود بديل).$q$, $q$Community-acquired pneumonia, uncomplicated and complicated skin infections, complicated intra-abdominal infections, plague, acute sinusitis and exacerbations of chronic bronchitis (sinusitis and bronchitis only when there is no alternative).$q$, $q$400 ملغ مرة يومياً فموياً أو وريدياً: الرئة 7 إلى 14 يوماً؛ الجلد البسيط 7، والمعقد 7 إلى 21؛ البطن 5 إلى 14؛ الطاعون 10 إلى 14؛ الجيوب 10؛ القصبات 5.$q$, $q$400 mg once a day by mouth or IV: pneumonia 7 to 14 days; uncomplicated skin 7, complicated 7 to 21; abdomen 5 to 14; plague 10 to 14; sinusitis 10; bronchitis 5.$q$, $q$لا تعديل في ضعف الكلى (ومنه الغسيل) أو الكبد.$q$, $q$No change for kidney impairment (including dialysis) or liver impairment.$q$, $q$مع الطعام أو بدونه، مع سوائل كافية. قبل منتجات المغنيسيوم والألومنيوم والحديد والزنك بـ 4 ساعات أو بعدها بـ 8. تحذير الملصق: التهاب الأوتار وتمزقها، والأعصاب الطرفية، والجهاز العصبي، وتفاقم الوهن العضلي.$q$, $q$With or without food, with plenty of fluids. 4 hours before or 8 hours after magnesium, aluminium, iron or zinc products. Label warning: tendon inflammation and rupture, peripheral nerves, central nervous system, and worsening of myasthenia gravis.$q$, '{93}', 930, false, false, false)
on conflict (id) do update set name_ar = excluded.name_ar, name_en = excluded.name_en, aware = excluded.aware, class_ar = excluded.class_ar, class_en = excluded.class_en, uses_ar = excluded.uses_ar, uses_en = excluded.uses_en, dose_ar = excluded.dose_ar, dose_en = excluded.dose_en, renal_ar = excluded.renal_ar, renal_en = excluded.renal_en, timing_ar = excluded.timing_ar, timing_en = excluded.timing_en, source_ids = excluded.source_ids, sort = excluded.sort, reviewed = false, deleted = false, updated_at = now();
delete from public.antibiotic_interactions where drug_id = 'moxi';
values ('oflox', $q$أوفلوكساسين$q$, $q$Ofloxacin$q$, 'watch', $q$فلوروكينولونات$q$, $q$Fluoroquinolones$q$, $q$تفاقم التهاب القصبات المزمن، والتهاب الرئة المكتسب، وعدوى الجلد البسيطة، والسيلان والكلاميديا في الإحليل وعنق الرحم، والتهاب الحوض الحاد، والتهاب المثانة، وعدوى المسالك المعقدة، والتهاب البروستات.$q$, $q$Exacerbations of chronic bronchitis, community-acquired pneumonia, uncomplicated skin infection, gonorrhoea and chlamydia of the urethra and cervix, acute pelvic inflammatory disease, cystitis, complicated urinary infection, and prostatitis.$q$, $q$القصبات والرئة والجلد: 400 ملغ كل 12 ساعة 10 أيام. السيلان: 400 ملغ مرة واحدة. الكلاميديا: 300 ملغ كل 12 ساعة 7 أيام. التهاب الحوض: 400 ملغ كل 12 ساعة 10 إلى 14 يوماً. التهاب المثانة: 200 ملغ كل 12 ساعة 3 أيام (الإشريكية أو الكلبسيلة) أو 7 أيام. المسالك المعقدة: 200 ملغ كل 12 ساعة 10 أيام. البروستات: 300 ملغ كل 12 ساعة 6 أسابيع.$q$, $q$Bronchitis, pneumonia, skin: 400 mg every 12 h for 10 days. Gonorrhoea: 400 mg once. Chlamydia: 300 mg every 12 h for 7 days. PID: 400 mg every 12 h for 10 to 14 days. Cystitis: 200 mg every 12 h for 3 days (E. coli or Klebsiella) or 7 days. Complicated urinary: 200 mg every 12 h for 10 days. Prostatitis: 300 mg every 12 h for 6 weeks.$q$, $q$بعد جرعة أولى عادية: التصفية 20 إلى 50 ← الجرعة المعتادة كل 24 ساعة؛ أقل من 20 ← نصف الجرعة كل 24 ساعة. تليف الكبد الشديد: لا يتجاوز 400 ملغ يومياً.$q$, $q$After a normal first dose: clearance 20 to 50 → the usual dose every 24 h; under 20 → half the dose every 24 h. Severe cirrhosis: not over 400 mg a day.$q$, $q$مع الطعام أو بدونه. لا مضادات حموضة أو حديد أو زنك أو سكرالفات خلال ساعتين قبله أو بعده. تحذير الملصق: الأوتار والأعصاب والجهاز العصبي والوهن العضلي.$q$, $q$With or without food. No antacids, iron, zinc or sucralfate within 2 hours before or after. Label warning: tendons, nerves, central nervous system and myasthenia gravis.$q$, '{94}', 940, false, false, false)
on conflict (id) do update set name_ar = excluded.name_ar, name_en = excluded.name_en, aware = excluded.aware, class_ar = excluded.class_ar, class_en = excluded.class_en, uses_ar = excluded.uses_ar, uses_en = excluded.uses_en, dose_ar = excluded.dose_ar, dose_en = excluded.dose_en, renal_ar = excluded.renal_ar, renal_en = excluded.renal_en, timing_ar = excluded.timing_ar, timing_en = excluded.timing_en, source_ids = excluded.source_ids, sort = excluded.sort, reviewed = false, deleted = false, updated_at = now();
delete from public.antibiotic_interactions where drug_id = 'oflox';
values ('norflox', $q$نورفلوكساسين$q$, $q$Norfloxacin$q$, 'watch', $q$فلوروكينولونات$q$, $q$Fluoroquinolones$q$, $q$للبالغين: التهاب المثانة الحاد غير المعقد (عند عدم ملاءمة الخيارات المعتادة) والمعقد، والتهاب الإحليل وعنق الرحم السيلاني، والتهاب البروستات الجرثومي، والتهاب الحويضة والكلية غير المعقد، والوقاية من التهاب السائل الحبني التلقائي في تليف الكبد.$q$, $q$Adults: acute uncomplicated cystitis (when the usual options are unsuitable) and complicated cystitis, gonococcal urethritis and cervicitis, bacterial prostatitis, uncomplicated pyelonephritis, and prevention of spontaneous bacterial peritonitis in cirrhosis.$q$, $q$التهاب المثانة غير المعقد: 400 ملغ مرتين يومياً 3 أيام. العدوى البولية الأخرى والسيلان: 800 ملغ يومياً (400 ملغ مرتين)، والمدة حسب الحالة. الوقاية في تليف الكبد: 400 ملغ مرة يومياً.$q$, $q$Uncomplicated cystitis: 400 mg twice a day for 3 days. Other urinary infections and gonorrhoea: 800 mg a day (400 mg twice), duration by condition. Prevention in cirrhosis: 400 mg once a day.$q$, $q$الجرعة نفسها ما دامت التصفية أكثر من 30. أقل من 30: لم تُحدد الجرعة وشروط الاستعمال.$q$, $q$Same dose while clearance is over 30. Under 30: dose and conditions of use not established.$q$, $q$مع كوب كبير من الماء، وليس مع الحليب أو مشتقاته. ممنوع للأطفال حتى نهاية النمو، ومع سوابق التهاب الأوتار بالكينولونات، وأثناء الرضاعة.$q$, $q$With a large glass of water, not with milk or dairy. Contraindicated in children until growth ends, with a history of quinolone tendinopathy, and during breastfeeding.$q$, '{95}', 950, false, false, false)
